// predicate p(i) is false,false,...,false,true,true...
int lo = lo0, hi = hi0, ans = -1;
while (lo <= hi) {
    int mid = lo + (hi - lo) / 2;
    if (p(mid)) { ans = mid; hi = mid - 1; }   // keep earlier truths
    else        lo = mid + 1;
}
return ans;

while (lo <= hi) {
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == t) return mid;
    if (a[lo] <= a[mid]) {                    // LEFT half sorted?
        if (a[lo] <= t && t < a[mid]) hi = mid - 1;
        else lo = mid + 1;
    } else {                                  // RIGHT half sorted
        if (a[mid] < t && t <= a[hi]) lo = mid + 1;
        else hi = mid - 1;
    }
}

// min in rotated: compare mid vs RIGHT end
while (lo < hi) {
    int mid = lo + (hi - lo) / 2;
    a[mid] > a[hi] ? lo = mid + 1 : hi = mid;   // min lives right of bigger-mid
}
// peak element: climb the uphill side
while (lo < hi) {
    int mid = lo + (hi - lo) / 2;
    a[mid] < a[mid+1] ? lo = mid + 1 : hi = mid;
}
